"""Build reviewed book records from saved publisher metadata. Research prerequisite."""
import json, re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
source=json.loads((ROOT/'research/candidates.json').read_text(encoding='utf-8'))
selection=[
 (0,'Văn học','Những trang ký ức về Hà Nội qua góc nhìn của Trung Sỹ.','Từ mái nhà quen đến những chặng đường nhiều biến động, Trung Sỹ nối chuyện riêng với diện mạo Hà Nội qua thời gian. Tập sách dành cho người thích tản văn và muốn quan sát một thành phố qua trải nghiệm của người sống trong nó.'),
 (2,'Văn học','Những câu chuyện về Lý Sơn và ký ức tuổi thơ nơi đảo nhỏ.','Lê Văn Chương dẫn người đọc đến đời sống và cảnh sắc Lý Sơn bằng những mẩu chuyện dễ tiếp cận. Ký ức tuổi nhỏ đan xen cùng hiểu biết về biển đảo, thích hợp để đọc chậm hoặc cùng trao đổi trong một buổi sinh hoạt đọc sách.'),
 (3,'Văn học','Tuổi thơ trong khu tập thể công nhân xây cầu Thăng Long.','Đặng Ngọc Hưng kể chuyện những đứa trẻ lớn lên cạnh công trường, nơi trò chơi và tình bạn đi cùng nhịp lao động của người lớn. Bối cảnh thời bao cấp mang đến một góc nhìn về ký ức tập thể và sự gắn bó trong đời sống thường ngày.'),
 (4,'Văn học','Truyện ngắn và tùy bút quan sát những điều bình dị quanh ta.','Phan Văn Trường đưa vào trang viết những cuộc gặp và sinh hoạt đời thường, với nhiều câu chuyện gắn cùng Sài Gòn. Người đọc có thể bắt đầu từ một bài ngắn, rồi tự tìm mối liên hệ giữa cách tác giả quan sát con người và trải nghiệm của mình.'),
 (5,'Văn học','Ghi chép của Vương Hồng Sển về một dấu tích Sài Gòn.','Cuốn sách lưu lại cách Vương Hồng Sển tiếp cận và ghi nhận Khám Lớn trước khi công trình bị tháo dỡ. Đây là lựa chọn cho độc giả quan tâm văn chương ký, tư liệu đô thị và việc ký ức một nơi chốn được lưu giữ qua lời kể cùng hình ảnh.'),
 (7,'Kỹ năng và phát triển bản thân','Góc nhìn của Tsunku về rèn luyện và thái độ làm việc.','Từ kinh nghiệm trong ngành âm nhạc, Tsunku bàn về cách một người phát triển năng lực qua công việc đều đặn và sự quan sát. Cuốn sách gợi ý cho bạn đọc trẻ nhìn lại thói quen học tập, cách chuẩn bị và trách nhiệm với việc mình đang làm.'),
 (10,'Kỹ năng và phát triển bản thân','Những câu chuyện học đường về áp lực so sánh.','Các nhân vật gặp những thước đo quen thuộc về điểm số, thành tích và hình ảnh bản thân. Qua chín truyện, người đọc có dịp suy nghĩ về ranh giới giữa học hỏi từ người khác và đặt lên mình kỳ vọng khó chịu; cha mẹ cũng có thể cùng đọc để mở đầu một cuộc trò chuyện.'),
 (11,'Kỹ năng và phát triển bản thân','Đọc về nỗi sợ đứng ngoài những điều mọi người đang theo đuổi.','Tập truyện đặt vấn đề FOMO trong đời sống học đường và các kết nối của thời đại số. Những tình huống gần gũi gợi cho người đọc cách nhìn lại lựa chọn, thời gian và nhu cầu được thuộc về một nhóm.'),
 (12,'Kỹ năng và phát triển bản thân','Câu chuyện học đường về cảm giác mình chưa đủ giỏi.','Tập sách khai thác nỗi ngại ngần khi một người chưa tin vào năng lực hoặc kết quả của chính mình. Hình thức truyện giúp người đọc trẻ quan sát cảm xúc qua nhân vật, rồi đặt câu hỏi về cách đánh giá bản thân và sự hỗ trợ từ người xung quanh.'),
 (13,'Kỹ năng và phát triển bản thân','Olga Khazan tìm hiểu khả năng thay đổi tính cách qua trải nghiệm.','Tác giả đặt những thử nghiệm cá nhân bên cạnh nghiên cứu về tính cách để xem hành vi hằng ngày có thể tạo ra thay đổi thế nào. Cuốn sách phù hợp với người thích đọc phi hư cấu và muốn suy nghĩ có căn cứ hơn về việc phát triển bản thân.'),
 (14,'Kinh tế và kinh doanh','Một góc phân tích các biến động kinh tế và thị trường.','Hai tác giả liên hệ bối cảnh kinh tế, chính sách và các chu kỳ thị trường để trình bày quan điểm của mình. Nên đọc như một góc nhìn để đối chiếu và đặt câu hỏi, thay vì coi các dự báo trong sách là kết quả chắc chắn hoặc chỉ dẫn giao dịch dành riêng cho bản thân.'),
 (16,'Kinh tế và kinh doanh','Chuyện nghề và kinh nghiệm trong lĩnh vực truyền thông thị giác.','Phan Trọng Bình chia sẻ quan sát từ công việc sáng tạo qua các bài viết ngắn. Ngoài chuyên môn, cuốn sách còn bàn về thái độ làm việc và cách giữ hứng thú với nghề, phù hợp cho sinh viên muốn tìm hiểu ngành quảng cáo, thiết kế và truyền thông.'),
 (17,'Kinh tế và kinh doanh','Suy nghĩ về tâm lý khách hàng và trách nhiệm của thương hiệu.','Nguyễn Khoa Hồng Thành bàn về những động lực bên trong lựa chọn của người tiêu dùng và cách thương hiệu tạo quan hệ với họ. Cuốn sách đặt ra câu hỏi về mục đích sử dụng hiểu biết tâm lý trong hoạt động tiếp thị, thích hợp cho người học marketing muốn mở rộng góc nhìn.'),
 (18,'Kinh tế và kinh doanh','Dan Heath bàn về cách nhận diện nguyên nhân trước khi vấn đề lặp lại.','Thay vì chỉ theo dõi việc xử lý sự cố, cuốn sách hướng sự chú ý đến các điều kiện tạo ra chúng. Những tình huống trong sách gợi cách xem xét quy trình, phối hợp và phòng ngừa, hữu ích để thảo luận về quản trị hoặc những việc đang lặp lại trong học tập.'),
 (19,'Kinh tế và kinh doanh','Đọc về quan hệ giữa công nghệ, quyền lực và sự thịnh vượng.','Daron Acemoglu và Simon Johnson khảo sát cách lựa chọn công nghệ gắn với lợi ích của các nhóm trong xã hội. Tác phẩm dành cho người muốn đọc sâu về kinh tế và lịch sử phát triển, đồng thời đặt câu hỏi ai được hưởng thành quả của thay đổi kỹ thuật.'),
 (21,'Tâm lý và đời sống','Kieran Setiya suy ngẫm về cách sống cùng những khó khăn.','Triết học trở thành điểm tựa để tác giả nhìn vào mất mát, cô đơn và những giới hạn của đời sống. Cuốn sách tạo không gian suy ngẫm về trải nghiệm con người, không đặt ra yêu cầu lúc nào người đọc cũng phải cảm thấy tích cực.'),
 (22,'Tâm lý và đời sống','Nhận diện những thiên kiến có thể ảnh hưởng cách nghĩ.','Hiroyuki đặt câu hỏi về các phán đoán tưởng như hiển nhiên và ảnh hưởng của chúng đến lựa chọn. Người đọc có thể dùng từng chủ đề làm gợi ý tự kiểm tra lập luận, chú ý hơn đến điều mình đang mặc định đúng khi giao tiếp hoặc tiếp nhận thông tin.'),
 (23,'Tâm lý và đời sống','Charles Wagner bàn về việc chọn điều thiết yếu trong đời sống.','Cuốn sách gợi người đọc xem lại những ưu tiên và ý nghĩa của lối sống giản dị. Đây là một lựa chọn đọc chậm: có thể dừng ở từng ý, liên hệ với đồ vật, công việc và các mối quan hệ đang chiếm thời gian của mình.'),
 (24,'Tâm lý và đời sống','Những suy ngẫm về cảm xúc và sự trưởng thành quanh tuổi ba mươi.','Park Yeji bàn đến trạng thái chông chênh khi trách nhiệm tăng lên mà cảm giác ổn định chưa đến. Cuốn sách gợi việc chú ý đến đời sống bên trong và cách ta xây dựng quan hệ với bản thân, phù hợp cho người đang muốn đọc và tự suy ngẫm về giai đoạn chuyển tiếp.'),
 (27,'Tâm lý và đời sống','Một cuốn sách dành cho người muốn nhìn lại thói quen lo nghĩ.','Kim Hye-nam bàn về những do dự trong đời sống trưởng thành và cách người đọc có thể suy xét lựa chọn của mình. Nội dung là điểm khởi đầu để tự quan sát cảm xúc và trao đổi, không thay thế việc hỗ trợ chuyên môn khi cần.'),
 (28,'Thiếu nhi','Khám phá lễ hội và tín ngưỡng dân gian ở Nam Bộ.','Qua lời kể của các bạn nhỏ, sách giới thiệu những lễ hội gắn với cộng đồng ở nhiều địa phương Nam Bộ. Người lớn có thể đọc cùng trẻ, trò chuyện về phong tục và khuyến khích các em kể lại một ngày hội mà mình từng biết.'),
 (29,'Thiếu nhi','Những lễ hội gắn với sông nước và biển ở Nam Bộ.','Cuốn sách đưa bạn đọc nhỏ tuổi tìm hiểu nét văn hóa ở Vĩnh Long, Cần Thơ và Cà Mau qua các ngày hội. Những câu chuyện là dịp để cùng nói về thiên nhiên, cộng đồng và cách mỗi nơi giữ gìn ký ức của mình.'),
 (31,'Thiếu nhi','Những mẩu chuyện để cùng trò chuyện về sự quan tâm.','Tập Tình yêu thương trong bộ 500 câu chuyện đạo đức tập trung vào tình cảm giữa người với người. Có thể chọn một câu chuyện cho mỗi lần đọc, rồi hỏi trẻ cảm nhận về hành động của nhân vật thay vì yêu cầu thuộc một bài học có sẵn.'),
 (32,'Thiếu nhi','Những câu hỏi ngắn giúp trẻ làm quen với nghệ thuật.','Vì sao con người vẽ tranh, dùng màu và sáng tạo? Cuốn sách đưa các chủ đề nghệ thuật đến gần bạn đọc nhỏ bằng hình thức hỏi đáp. Sau khi đọc, trẻ có thể thử vẽ hoặc kể về một bức tranh theo cách nhìn riêng của mình.'),
 (33,'Thiếu nhi','Cùng trẻ đặt câu hỏi về thế giới và các hiện tượng quanh mình.','Sách mở đầu từ những thắc mắc gần gũi về Trái Đất, thời tiết và thế giới con người. Cách trình bày hỏi đáp phù hợp với những buổi đọc ngắn; người lớn có thể khuyến khích trẻ tiếp tục quan sát và ghi lại câu hỏi mới.'),
]
records=[]
for i,(index,category,short,description) in enumerate(selection,1):
    s=source[index]; m=s['metadata']
    def field(label):
        match=re.search(re.escape(label)+r'\s*\n(.*?)(?=\n[^\n]*:|\nIn lần thứ|$)',m,re.S)
        return re.sub(r'\s+', ' ',match.group(1)).replace(' , ', ', ').strip() if match else ''
    isbn=re.search(r'978-[\d-]+',m).group()
    year=re.search(r'In lần thứ\s+(\d+) năm (\d{4})',m)
    records.append(dict(sku=f'MT-{i:03}',title=s['title'],category=category,author=field('Tác giả:'),publisher='Nhà xuất bản Trẻ',pages=int(field('Số trang:')),size=field('Khổ sách:'),isbn=isbn,edition=int(year[1]),year=int(year[2]),language='Tiếng Việt',reference_price=int(re.sub(r'\D','',field('Giá bán:'))),demo_price=(int(re.sub(r'\D','',field('Giá bán:')))*9//10000)*1000,stock=10+i%6,short=short,description=description,url=s['url'],accessed='2026-11-04',featured=1 if (i-1)%5==0 else 0))
(ROOT/'data/books.json').write_text(json.dumps(records,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('Prepared',len(records),'reviewed edition records')
